css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f8f5;color:#122c36;font:16px/1.7 system-ui,-apple-system,sans-serif}a{color:#176952;text-underline-offset:4px}button,input,select,textarea{font:inherit}button,a,input,select,textarea,summary{outline-offset:5px}header{background:#fff;border-bottom:1px solid #dde4df;position:sticky;top:0;z-index:10}.top{background:#122c36;color:#e0ece5;font-size:12px;text-align:center;padding:7px 15px;letter-spacing:1px}.bar{max-width:1320px;padding:19px 5%;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:25px}.brand{display:flex;align-items:center;text-decoration:none;color:#122c36}.brand svg{width:43px;height:43px;margin-right:12px}.brand b{font-size:23px;letter-spacing:4px;display:block}.brand small{display:block;font-size:9px;letter-spacing:.1px;max-width:220px;line-height:1.4}nav{display:flex;gap:23px;align-items:center}nav a{text-decoration:none;font-size:13px;color:#344a50}nav a[aria-current]{color:#176952;border-bottom:2px solid #176952}.menu{display:none}main{max-width:1320px;margin:auto;padding:0 5%}h1,h2{font-family:Georgia,serif;font-weight:400;line-height:1.1;letter-spacing:-1.6px}h1{font-size:clamp(42px,5.6vw,76px);max-width:850px;margin:18px 0 26px}h2{font-size:clamp(31px,3.4vw,43px);margin:12px 0 22px}h3{font-size:18px;line-height:1.4}p{color:#496067;max-width:780px}.eyebrow{font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#176952}.hero{padding:72px 0 62px;display:grid;grid-template-columns:1.4fr 1fr;gap:65px;align-items:center}.intro{padding:60px 0 32px}.lead{font-size:19px}.button,button{display:inline-flex;align-items:center;gap:20px;padding:12px 22px;background:#176952;color:white;border:1px solid #176952;text-decoration:none;border-radius:3px;cursor:pointer;font-weight:600;font-size:14px}.secondary{background:transparent;color:#176952}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}section{padding:42px 0;border-top:1px solid #dce4de}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.two{display:grid;grid-template-columns:1fr 1fr;gap:28px}.card{background:#fff;border:1px solid #dde4df;padding:28px;border-radius:5px}.card p{font-size:14px}.number{color:#176952;font:36px Georgia}.cover{background:#122c36;padding:30px;color:#fff;aspect-ratio:3/4;width:100%;max-width:330px;margin:auto;box-shadow:18px 18px 0 #e1e8df;border-radius:2px;position:relative;overflow:hidden}.cover svg{width:44px;height:44px;background:#f4f2e9;border-radius:2px}.cover h2{font-size:32px;position:relative;z-index:2}.cover .wave{position:absolute;width:500px;height:330px;bottom:-180px;left:-90px;border-radius:45%;background:repeating-radial-gradient(ellipse at center,#176952 0 2px,#234c48 3px 12px);transform:rotate(-23deg)}.cover small{position:absolute;bottom:18px;left:30px;z-index:2;letter-spacing:2px;font-size:9px}.tag{display:inline-block;font-size:11px;padding:4px 10px;border:1px solid #c6d5c9;border-radius:30px;color:#176952}.notice{padding:20px 25px;background:#e9efe7;border-left:3px solid #176952;border-radius:2px;color:#344a50;font-size:14px}.split{display:grid;grid-template-columns:230px 1fr;gap:50px;padding:25px 0 60px}.side{align-self:start;position:sticky;top:125px}.side a{display:block;padding:8px 0;font-size:14px}.content section:first-child{border-top:0;padding-top:0}.content h2{font-size:32px}.content li{margin:9px 0;color:#496067}details{background:#fff;border:1px solid #dde4df;padding:18px 22px;margin:12px 0;border-radius:4px}summary{cursor:pointer;font-weight:600}.empty{text-align:center;padding:65px 20px;background:#fff;border:1px solid #dde4df;border-radius:6px}.empty p{margin:15px auto}.form label{display:block;font-size:13px;font-weight:600;margin-bottom:16px}.form input,.form select,.form textarea{display:block;width:100%;padding:11px 12px;margin-top:5px;border:1px solid #c6d3ca;background:#fff;border-radius:3px;color:#122c36}.checks label{display:flex;gap:12px;align-items:start;padding:13px 0;border-bottom:1px solid #e1e8e2;font-size:14px}.checks input{display:inline-block;width:18px;height:18px;flex:0 0 18px;margin:4px 0 0;accent-color:#176952}.muted{font-size:13px;color:#63777c}.result{padding:16px;background:#e9efe7;margin:20px 0;border-radius:4px}footer{background:#122c36;color:#fff;margin-top:50px;padding:45px 6% 25px}footer .inner{max-width:1180px;margin:auto}footer p,footer a{color:#bfd0cc;font-size:13px}footer .links{display:flex;gap:22px;flex-wrap:wrap}footer hr{border:0;border-top:1px solid #3b5358;margin:28px 0}.skip{position:absolute;top:-100px}.skip:focus{top:0;background:white;z-index:100;padding:10px}table{border-collapse:collapse;width:100%}td,th{padding:13px;text-align:left;border-bottom:1px solid #dce4de;font-size:14px}.tablewrap{overflow:auto}@media(max-width:950px){nav{display:none;position:absolute;top:83px;left:0;right:0;background:#fff;padding:25px;box-shadow:0 10px 20px #122c3610}nav.open{display:flex;flex-direction:column;align-items:start}.menu{display:block;background:white;color:#176952;padding:8px 13px}.hero{gap:30px}.split{grid-template-columns:1fr}.side{position:static;display:flex;gap:16px;flex-wrap:wrap}.grid{grid-template-columns:1fr}.brand small{font-size:8px}}@media(max-width:620px){.hero,.two{grid-template-columns:1fr}.hero{padding:40px 0}.cover{width:260px}.intro{padding-top:35px}h1{letter-spacing:-1px}.bar{padding:14px 5%}.top{font-size:10px}nav{top:75px}.card{padding:22px}}'''
(D/'style.css').write_text(css)
js='''const toggle=document.querySelector('.menu'),nav=document.querySelector('nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Close':'Menu'});const form=document.querySelector('#prep');if(form){const fields=['title','type','abstract'];try{const draft=JSON.parse(localStorage.getItem('jecde-draft')||'{}');fields.forEach(k=>{if(draft[k])form.elements[k].value=draft[k]})}catch{}form.addEventListener('input',()=>{try{localStorage.setItem('jecde-draft',JSON.stringify(Object.fromEntries(fields.map(k=>[k,form.elements[k].value]))))}catch{}});form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const checks=[...form.querySelectorAll('[type=checkbox]')];const done=checks.filter(c=>c.checked).length;document.querySelector('#prep-result').textContent=done+' of '+checks.length+' readiness checks completed. This is a local preparation tool; no manuscript has been submitted.';const text='JECDE — Manuscript preparation record\\n\\nTitle: '+form.elements.title.value+'\\nArticle type: '+form.elements.type.value+'\\nAbstract: '+form.elements.abstract.value+'\\n\\nReadiness checks\\n'+checks.map(c=>(c.checked?'[x] ':'[ ] ')+c.parentElement.textContent.trim()).join('\\n')+'\\n\\nPreparation record only. Not a submission or editorial decision.';const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='JECDE-manuscript-preparation.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});document.querySelector('#clear').addEventListener('click',()=>{form.reset();try{localStorage.removeItem('jecde-draft')}catch{}document.querySelector('#prep-result').textContent='Local draft cleared.'})}'''
(D/'app.js').write_text(js)
def page(file,title,body):
 n=''.join(f'<a href="{url}" '+('aria-current="page"' if url==file else '')+f'>{label}</a>' for url,label in nav)
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="JECDE — Journal of Electrical, Computer and Digital Engineering. Explore the journal scope, author guidance and proposed editorial policies."><meta name="theme-color" content="#176952"><title>{title} | JECDE</title><link rel="icon" href="mark.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="top">FOUNDING EDITION · SUBMISSIONS NOT YET OPEN</div><header><div class="bar"><a class="brand" href="index.html" aria-label="JECDE home">{logo}<span><b>JECDE</b><small>Journal of Electrical, Computer and Digital Engineering</small></span></a><button class="menu" aria-controls="navigation" aria-expanded="false">Menu</button><nav id="navigation" aria-label="Main navigation">{n}</nav></div></header><main id="main">{body}</main><footer><div class="inner"><div class="two"><div><div style="font-size:24px;letter-spacing:4px">JECDE</div><p>Clear thinking. Connected knowledge.<br>Journal of Electrical, Computer and Digital Engineering</p></div><div class="links"><a href="authors.html">Author guidelines</a><a href="policies.html">Publication ethics</a><a href="fees.html">Fees &amp; access</a><a href="privacy.html">Privacy</a><a href="contact.html">Contact &amp; status</a></div></div><hr><p>Founding concept · Working name subject to clearance. Publisher registration and editorial appointments are pending. No ISSN, DOI registration, indexing or association membership is claimed.</p><p>© 2026 JECDE project. Website content is informational; final operating policies will be approved before submissions open.</p></div></footer></body></html>'''
 (D/file).write_text(html)
def intro(k,t,p):return f'<div class="intro"><div class="eyebrow">{k}</div><h1>{t}</h1><p class="lead">{p}</p></div>'
page('index.html','Electrical, Computer and Digital Engineering',f'''<div class="hero"><div><span class="tag">Independent journal · In development</span><h1>Clear thinking.<br>Connected knowledge.</h1><p class="lead">A scientific home for electrical engineering, electronics, computing, communications, artificial intelligence and cybersecurity.</p><p>Connected disciplines. Transparent review. Research that advances electrical, computing and digital technologies.</p><div class="actions"><a class="button" href="about.html">Explore the journal ↗</a><a class="button secondary" href="authors.html">Prepare your manuscript</a></div></div><div class="cover">{logo}<p style="color:#bad2c7;font-size:11px;letter-spacing:3px">JECDE</p><h2>Electrical,<br>Computer<br>&amp; Digital<br>Engineering</h2><div class="wave"></div><small>COVER CONCEPT · FOUNDING EDITION</small></div></div><section><div class="eyebrow">The research agenda</div><h2>Engineering across connected disciplines.</h2><div class="grid"><div class="card"><div class="number">01</div><h3>Electrical Engineering</h3><p>Power systems, renewable energy, electrical machines, control and automation.</p></div><div class="card"><div class="number">02</div><h3>Electronics</h3><p>Electronic circuits, semiconductor devices, instrumentation and embedded systems.</p></div><div class="card"><div class="number">03</div><h3>Computing</h3><p>Computer architecture, software engineering, algorithms and distributed computing.</p></div><div class="card"><div class="number">04</div><h3>Communications</h3><p>Wireless and optical communications, signal processing and communication networks.</p></div><div class="card"><div class="number">05</div><h3>Artificial Intelligence</h3><p>Machine learning, intelligent systems, robotics and trustworthy AI.</p></div><div class="card"><div class="number">06</div><h3>Cybersecurity</h3><p>Network and system security, cryptography, privacy and digital forensics.</p></div><div class="card"><div class="number">07</div><h3>Digital Technologies</h3><p>Internet of Things, digital twins, cloud and edge computing, and digital infrastructure.</p></div></div></section><section><div class="two"><div><div class="eyebrow">Editorial principles</div><h2>Rigor at every stage.</h2><p>Our proposed framework separates financial decisions from editorial judgment and makes the research assessment process explicit.</p><a href="review.html">Understand peer review →</a></div><div class="card"><h3>What a strong submission demonstrates</h3><p>A clear research question, supported novelty, fully defined methods, appropriate baselines and evidence that can be inspected.</p><a href="authors.html">Read the author guidelines →</a></div></div></section><section><div class="eyebrow">Publication status</div><h2>The first chapter is being built.</h2><div class="notice">No articles or issues have been published. Submissions and payments remain closed while the publisher, editorial board and publishing infrastructure are established.</div><div class="actions"><a class="button secondary" href="contact.html">View launch readiness</a><a href="articles.html">Browse the publication archive →</a></div></section>''')
page('about.html','About the journal',intro('About JECDE','A shared forum for engineering and digital research.','A proposed English-language, open-access journal spanning electrical, electronic, computing and digital disciplines.')+'''<section><div class="two"><div><h2>Aims &amp; scope</h2><p>The journal welcomes original theoretical, methodological and experimental contributions across its seven subject tracks. Interdisciplinary work is encouraged when its contribution and evaluation are clearly established.</p><ul><li><b>Electrical Engineering:</b> Power systems, renewable energy, electrical machines, control and automation.</li><li><b>Electronics:</b> Electronic circuits, semiconductor devices, instrumentation and embedded systems.</li><li><b>Computing:</b> Computer architecture, software engineering, algorithms and distributed computing.</li><li><b>Communications:</b> Wireless and optical communications, signal processing and communication networks.</li><li><b>Artificial Intelligence:</b> Machine learning, intelligent systems, robotics and trustworthy AI.</li><li><b>Cybersecurity:</b> Network and system security, cryptography, privacy and digital forensics.</li><li><b>Digital Technologies:</b> Internet of Things, digital twins, cloud and edge computing, and digital infrastructure.</li></ul></div><div class="card"><h3>Outside the scope</h3><p>Work outside the listed disciplines; unsupported performance claims; descriptive implementations without substantive research evaluation; and manuscripts without a clear scientific or engineering contribution.</p><h3>Article types</h3><p>Original research and critical reviews. Reviews should explain literature selection and provide synthesis beyond a catalogue of publications.</p></div></div></section><section><h2>Editorial governance</h2><p>Recruitment of the editor-in-chief and subject editors is pending. No individual or institution is represented as an appointed editor or sponsor.</p><div class="grid"><div class="card"><h3>Editor-in-chief</h3><p>Responsible for editorial standards, appeals oversight and the integrity of the journal.</p><span class="tag">Appointment pending</span></div><div class="card"><h3>Subject editors</h3><p>Manage suitable submissions, select independent reviewers and assess the evidence.</p><span class="tag">Recruitment planned</span></div><div class="card"><h3>Independent handling</h3><p>Submissions involving owners or editors require a conflict-free editor and disclosed procedures.</p><span class="tag">Proposed safeguard</span></div></div></section>''')
page('articles.html','Articles & archive',intro('Articles & archive','Research begins with evidence.','The publication archive will appear here after the first peer-reviewed articles are published.')+'''<div class="empty"><div class="eyebrow">Publication archive</div><h2>No published articles yet.</h2><p>No volumes, issues, citations or metrics are displayed because publication has not begun.</p><a class="button secondary" href="about.html">Explore the journal scope</a></div><section><h2>Planned article experience</h2><div class="grid"><div class="card"><h3>Accessible full text</h3><p>Article landing pages with abstracts, author details and downloadable publication files.</p></div><div class="card"><h3>Research context</h3><p>Funding, conflicts, data availability, contributions and publication history.</p></div><div class="card"><h3>Persistent records</h3><p>Verified identifiers, metadata and preservation arrangements will be displayed once activated.</p></div></div></section>''')
page('authors.html','Author guidelines',intro('For authors','Make your research assessable.','Practical guidance for preparing a clear, complete manuscript. Submissions are not yet open.')+'''<div class="split"><aside class="side"><a href="#structure">Manuscript structure</a><a href="#evidence">Methods &amp; evidence</a><a href="#files">Submission files</a><a href="prepare.html">Preparation tool ↗</a></aside><div class="content"><section id="structure"><h2>Manuscript structure</h2><ol><li><b>Title and authors:</b> precise title, affiliations, corresponding author and available ORCID identifiers.</li><li><b>Abstract and keywords:</b> explain the problem, method, main supported findings and implications. Define abbreviations where needed.</li><li><b>Introduction:</b> establish the problem, relevant literature, research gap and contributions.</li><li><b>Methods or system model:</b> specify assumptions, symbols, algorithms, datasets, hardware and implementation details.</li><li><b>Results and discussion:</b> compare appropriate baselines, explain observed behavior, report uncertainty and discuss limitations.</li><li><b>Conclusion:</b> distinguish demonstrated findings from future work.</li><li><b>Declarations and references:</b> disclose funding, interests, author contributions, data and code availability.</li></ol></section><section id="evidence"><h2>Methods &amp; evidence</h2><p>Define metrics and units. Provide fair comparisons and justify parameter choices. Report random seeds or repeatability procedures where applicable. Identify data provenance, access conditions and relevant approvals.</p><p>Every figure and table should be cited in the text. Use readable axes, descriptive captions and accessible colour choices. Define abbreviations on first use and verify reference details.</p><p>Do not fabricate results, citations or identifiers. Describe simulation and experimental findings accurately, with clear limits to generalization.</p></section><section id="files"><h2>Files to prepare</h2><ul><li>Editable manuscript and a matching PDF</li><li>Figures at publication quality and editable tables</li><li>A cover letter explaining fit, originality and related submissions</li><li>Supplementary data or code, or a justified availability statement</li><li>Required declarations and any permissions for reused material</li></ul><div class="notice">The JECDE LaTeX template is available for manuscript preparation. Final operating requirements remain subject to editorial approval. The preparation tool creates a personal checklist, not a journal submission.</div><div class="actions"><a class="button" href="templates.html">Download LaTeX template ↗</a><a class="button secondary" href="prepare.html">Open preparation tool</a><a class="button secondary" href="fees.html">Fees &amp; waivers</a></div></section></div></div>''')
page('prepare.html','Manuscript preparation',intro('Local author workspace','Prepare with confidence.','Create a downloadable preparation record. Your title and abstract stay in this browser; nothing is sent to the journal.')+'''<div class="two"><form id="prep" class="card form"><label>Manuscript title<input name="title" required maxlength="400" autocomplete="off"></label><label>Article type<select name="type"><option>Original research</option><option>Critical review</option></select></label><label>Working abstract<textarea name="abstract" rows="6" required maxlength="10000"></textarea></label><div class="checks"><label><input type="checkbox">The manuscript fits the journal scope.</label><label><input type="checkbox">All authors have approved the manuscript.</label><label><input type="checkbox">Methods, metrics and baselines are adequately defined.</label><label><input type="checkbox">References and reported results have been verified.</label><label><input type="checkbox">Funding, conflicts and data availability are declared.</label><label><input type="checkbox">Permissions and relevant research approvals are addressed.</label></div><div class="actions"><button type="submit">Download preparation record</button><button type="button" class="secondary" id="clear">Clear local draft</button></div><p id="prep-result" class="result" role="status">No manuscript has been submitted.</p></form><div><h2>Before you begin</h2><p>This browser tool helps organize your manuscript. It does not upload files, create an author account or initiate peer review.</p><p>Title, article type and abstract are saved on this device when browser storage is available. Checklist selections are not saved. Avoid entering confidential content on a shared device and clear your draft afterwards.</p><a href="privacy.html">Read the privacy notice →</a><div class="notice" style="margin-top:25px">The production manuscript portal is not active. No submission fee or publication payment can be collected here.</div></div></div>''')
page('review.html','Peer review',intro('Proposed review framework','Independent judgment.<br>Explicit criteria.','A transparent assessment process designed to evaluate significance, validity and clarity.')+'''<section><div class="grid"><div class="card"><div class="number">01</div><h3>Editorial screening</h3><p>Scope, completeness, originality concerns, declarations and readiness for expert evaluation.</p></div><div class="card"><div class="number">02</div><h3>External assessment</h3><p>At least two independent expert reports under the proposed internal policy. Reviewer conflicts must be disclosed.</p></div><div class="card"><div class="number">03</div><h3>Reasoned decision</h3><p>Acceptance, revision or rejection based on evidence. Revisions should address each substantive comment.</p></div></div></section><section><h2>Reviewer guidance</h2><p>Assess the research question, novelty, methodological validity, evidence, reproducibility, limitations and presentation. Separate essential corrections from optional suggestions. Provide specific, respectful comments supported by the manuscript.</p><details open><summary>Confidentiality and responsible tool use</summary><p>Keep manuscripts and reviews confidential. Do not upload unpublished material into external AI services without authorization. Disclose any conflict or inability to evaluate the work competently.</p></details><details><summary>Review model and timelines</summary><p>The final anonymity model and service targets will be published before submissions open. No acceptance or review completion time is guaranteed.</p></details><details><summary>Appeals</summary><p>Authors may request a reasoned reconsideration supported by specific evidence. A conflict-free editor should assess the appeal. A disagreement alone does not establish an error.</p></details></section>''')
policies=[('Authorship & contributions','Authorship should reflect substantive contribution and accountability. All authors must approve the submitted version. Explain changes to the author list and obtain agreement from affected contributors.'),('Originality & research integrity','Submit original work and disclose related manuscripts, preprints and overlapping material. Plagiarism, fabricated data, manipulated evidence and undisclosed duplicate publication are unacceptable. Concerns should be investigated fairly with an opportunity to respond.'),('Competing interests & funding','Declare financial and nonfinancial interests and describe sponsor involvement. Editorial conflicts require reassignment to an independent editor. Fee status must not determine scientific decisions.'),('Data, code & reproducibility','Include an availability statement with repository links and access conditions where possible. Explain justified restrictions, including privacy, contractual or security constraints. Do not claim unrestricted access where it is not provided.'),('AI-assisted work','Authors remain accountable for accuracy, originality and references. Disclose substantive AI assistance and verify all outputs. AI systems cannot take authorship responsibility. Confidential manuscripts should not be shared with unauthorized third-party services.'),('Corrections, expressions of concern & retractions','Maintain a transparent publication record. Material post-publication errors may require a linked correction, an expression of concern or retraction following assessment. Preserve notices and explain the reason for the action.'),('Complaints & appeals','Provide the article or decision involved, supporting evidence and the remedy sought. Complaints involving an editor should be reviewed independently. A formal contact channel must be activated before submissions open.'),('Research involving people, animals or sensitive data','Report applicable ethics approvals, consent and data protection measures. Editors may request evidence. Authors must comply with requirements applicable to their research and institutions.')]
page('policies.html','Editorial policies',intro('Draft policy framework','Standards that protect the record.','These proposed policies will be finalized and versioned before the journal accepts submissions.')+'<section>'+''.join('<details'+(' open' if i==0 else '')+'><summary>'+t+'</summary><p>'+p+'</p></details>' for i,(t,p) in enumerate(policies))+'</section><div class="notice">This framework does not represent membership in or endorsement by any publishing standards organization.</div>')
page('fees.html','Fees & open access',intro('Fees & access','Transparent costs.<br>Independent decisions.','The journal proposes an open-access model. No payment facility is active.')+'''<section><div class="two"><div><h2>Publication charges</h2><p>A final article processing charge has not been approved. No fee is currently payable. A complete schedule, currency, taxes where applicable and refund conditions must be published before submissions open.</p><p>The intended model is invoicing after editorial acceptance, with fee administration separated from scientific decisions.</p></div><div class="card"><h3>Waivers &amp; discounts</h3><p>A budgeted waiver programme is proposed. Eligibility, application timing and assessment procedures remain to be finalized. No waiver or discount is guaranteed by this website.</p></div></div></section><section><h2>Copyright &amp; reuse</h2><p>The proposed model allows authors to retain copyright and publish under a CC BY licence. Final publication agreements and the applicable licence version will be disclosed before authors commit to publication.</p><h2>Identifiers &amp; preservation</h2><p>ISSN allocation, DOI registration and long-term preservation arrangements are pending. These services will be described as active only after verification.</p></section>''')
page('privacy.html','Privacy & website terms',intro('Privacy & terms','Know what this site does.','A concise notice for the current founding website and its local preparation tool.')+'''<section><h2>Local preparation data</h2><p>The preparation tool stores your manuscript title, article type and abstract in browser local storage when available. This application does not send these entries to the journal. Use “Clear local draft” to remove them, or clear the site data in your browser.</p><h2>Hosting and access</h2><p>Hosting and authentication providers may process technical access information under their own terms. This website does not provide a journal account system or a payment processor.</p><h2>Cookies &amp; analytics</h2><p>No advertising trackers or analytics scripts have been added to this application. Browser local storage is used only by the preparation tool. Hosting-level access controls may use separate authentication mechanisms.</p><h2>Website terms</h2><p>The content describes a founding project and proposed policies. It does not constitute an offer of publication, an editorial appointment or a claim of registration or indexing. Do not submit confidential research by an unverified channel.</p><h2>Future operational notice</h2><p>A complete publisher identity, contact address, applicable privacy information and retention procedures must be published before the journal collects submission or payment data.</p></section>''')
page('contact.html','Contact & launch status',intro('Contact & launch readiness','Building the foundation first.','The journal is in its founding stage. Author submissions, payments and editorial applications are not currently collected through this site.')+'''<section><div class="two"><div><h2>Editorial office</h2><p>A dedicated journal email address and verified publisher contact details have not yet been activated. No contact form is provided because there is no configured recipient or delivery service.</p><p>Founding project prepared for Dr. Yassir Al-Karawi. This does not imply sponsorship or endorsement by any university.</p></div><div class="card"><h3>Current website capabilities</h3><p>Journal information, draft editorial policies, author guidance, publication status and a browser-local preparation record.</p><h3>Before submissions open</h3><p>Verified publisher details, appointed editors, an operational manuscript portal, approved fees and agreements, and preservation arrangements.</p></div></div></section><section><h2>Launch readiness</h2><div class="tablewrap"><table><tr><th>Workstream</th><th>Status</th></tr><tr><td>English website &amp; visual identity</td><td>Implemented</td></tr><tr><td>Author guidance &amp; policy framework</td><td>Draft published for review</td></tr><tr><td>Publisher registration &amp; name clearance</td><td>Pending owner decisions and verification</td></tr><tr><td>Editorial appointments</td><td>Pending written consent</td></tr><tr><td>Manuscript submission portal</td><td>Not active</td></tr><tr><td>Payment collection</td><td>Not active</td></tr><tr><td>ISSN, DOI &amp; preservation</td><td>Pending arrangements</td></tr><tr><td>Indexing</td><td>No indexing claimed</td></tr></table></div></section>''')
